arguments.command:
cat > /tmp/gh-askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *sername*) echo "x-access-token" ;;
  *assword*) echo "$GITHUB_TOKEN" ;;
  *) echo "" ;;
esac
EOF
chmod +x /tmp/gh-askpass.sh && GIT_ASKPASS=/tmp/gh-askpass.sh GIT_TERMINAL_PROMPT=0 git -C /home/runner/work/beetle-in-the-anthill/joey-conv push origin HEAD:refs/heads/friend/joey 2>&1 | tail -5
